
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m06_sx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m06_sx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.530955925819762e-02, -8.466300852714075e-02, -8.372673932893894e-02, -8.236648922168276e-02, -8.038012052553292e-02, -7.745514242191429e-02, -7.308552081391860e-02, -6.637856204780340e-02, -5.551282851198738e-02, -3.682270199429146e-02, -2.003444787781058e-02, -7.442324446542153e-02, -4.914339555756359e-02, -3.212792924851282e-02, -1.574676507191398e-02, 9.755879539506082e-03, 2.240233907211719e-02, 7.665932458384335e-03, 7.981194303582934e-04, 2.480837240936410e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


